//! Generated Rust: the data part of `grammars/<g>/mod.rs`.

use crate::blob::{Blob, COUNT_KEYS, LangInfo};
use crate::lock::LockEntry;
use crate::parse::Grammar;

/// The two header lines of every generated file.
pub fn header(l: &LockEntry, sum: &str) -> String {
    format!(
        "// @generated by gengrammar from {}@{}. DO NOT EDIT.\n// Source: {}/parser.c, sha256 {sum}.\n",
        l.module, l.version, l.dir
    )
}

fn names(g: &Grammar, table: &str) -> String {
    let strs = g.tables.get(table).map_or(&[][..], |t| &t.strs[..]);
    let list: Vec<String> = strs.iter().map(|s| format!("{s:?}")).collect();
    list.join(", ")
}

/// The text of `mod.rs`: constants, offsets and names. `language()` comes with the runtime.
pub fn mod_rs(hdr: &str, g: &Grammar, info: &LangInfo, blob: &Blob) -> String {
    let mut s = format!("{hdr}\n#![allow(non_upper_case_globals)]\n");
    for en in &g.enums {
        s.push_str(&format!("\n// enum {}\n", en.name));
        for (n, v) in en.names.iter().zip(&en.vals) {
            s.push_str(&format!("pub const {n}: u16 = {v};\n"));
        }
    }
    // The numeric keys of TSLanguage; one that is not set is 0, as in C. `version` is the old
    // name of `abi_version`.
    let fields: Vec<(&str, &str)> = COUNT_KEYS
        .iter()
        .filter(|k| k.0 != "version")
        .map(|k| (k.1, k.2))
        .collect();
    s.push_str("\npub struct Counts {\n");
    for (f, ty) in &fields {
        s.push_str(&format!("    pub {f}: {ty},\n"));
    }
    s.push_str("}\n\npub const COUNTS: Counts = Counts {\n");
    for (f, _) in &fields {
        let v = info.counts.iter().find(|c| c.0 == *f).map_or(0, |c| c.1);
        s.push_str(&format!("    {f}: {v},\n"));
    }
    s.push_str("};\n\n");
    for sec in &blob.sections {
        s.push_str(&format!(
            "pub const {}: (usize, usize) = ({}, {});\n",
            sec.name.to_uppercase(),
            sec.offset,
            sec.count
        ));
    }
    s.push_str(&format!(
        "\npub static SYMBOL_NAMES: &[&str] = &[{}];\npub static FIELD_NAMES: &[&str] = &[{}];\n",
        names(g, &info.symbol_names),
        names(g, &info.field_names)
    ));
    s.push_str("\n#[allow(dead_code)] // read by language()\nstatic TABLES: &[u8] = include_bytes!(\"tables.bin\");\n");
    s
}
